head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil15303";
scwin.title = null;
scwin.keyword = null;
scwin.contn = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — lawList

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.title = "${fn:replace(law.lawItmTitle, \"\"\", \"\\\"\")}";
        scwin.keyword = "${fn:replace(param.keyword, \"\"\", \"\\\"\")}";
        scwin.contn = "${fn:replace(law.lawItmContn, \"\"\", \"\\\"\")}";
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil15303.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "td_40", attr: "__html", fn: function () { return ([String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : ""))(dma_pageContext.get("keyword")))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("<span class=\"search\">'" + String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : ""))(dma_pageContext.get("keyword"))) + "'</span> 검색결과") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_42", fn: function(){ return (!(String(((dma_pageContext.get("lawList") ?? "")) == null ? '' : ((dma_pageContext.get("lawList") ?? ""))).length === 0)); } }, { id: "c_otherwise_88", fn: function(){ return (!((!(String(((dma_pageContext.get("lawList") ?? "")) == null ? '' : ((dma_pageContext.get("lawList") ?? ""))).length === 0)))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : ""))(dma_pageContext.get("keyword"))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_29_onclick
 * @description img_29 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_29_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15303.img_29_onclick' }); }
};

/**
 * @method
 * @name grd_lawList_oncellclick
 * @description grd_lawList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_lawList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_lawList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_lawList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.lawItemView(r["lawNo"], r["linkLawItmSeq"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_lawList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_86_onclick
 * @description krxpage_pagenavigator_86 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_86_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_LawItemViewReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_86.page' }); } await scwin.search(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_LawItemView
 * @description Law Item View 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_LawItemView = async function () {
    const sbmOptions = {
        id: "tx_fn_LawItemView",
        method: "post",
        action: "/support/popLaw.do",
        ref: "dma_LawItemViewReq",
        target: "dlt_lawList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/support/law.do",
        ref: "dma_SearchReq",
        target: "dlt_lawList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name lawItemView
 * @description law Item View 처리
 * @param {*} _lawNo _lawNo
 * @param {*} _lawItmSeq _lawItmSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.lawItemView = async function (_lawNo, _lawItmSeq) {
    const frm = (document.fn_LawItemView || { elements: [] });
    $c.util.getComponent('dma_LawItemViewReq').set('lawNo', _lawNo);
    $c.util.getComponent('dma_LawItemViewReq').set('lawItmSeq', _lawItmSeq);
    $c.util.getComponent('dma_LawItemViewReq').set('method', "viewLawItemTemplete");
    frm.action = "popLaw.do";
    frm.target = "viewLawItem";
    $c.win.openPopup("", { id: "viewLawItem", scrollbars: true, resizable: false, width: "440", height: "500", type: "pageFramePopup" }, {});
    const nr = await scwin.tx_fn_LawItemView();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil15302/jldfil15302.xml", { "lawNo": _lawNo, "lawItmSeq": _lawItmSeq, "method": "viewLawItemTemplete" });
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const frm = (document.lawSearchForm || { elements: [] });
    $c.util.getComponent('dma_LawItemViewReq').set('method', "searchLawByKeyword");
    frm.action = "law.do";
    await scwin.tx_fn_Search();
};
